#!/usr/bin/env node
// rynth/vt/tools/gen_creature_species.cjs — generator for
// rynth/vt/data/creature_species.json (PLAN W1-7 CMB, M23 `species`).
//
// Output: { v: 1, names: { "<CreatureType int>": "<display name>" },
//           wcid: { "<wcid>": <CreatureType int> } }
//
//   wcid   every creature row (itemType 16) of the LSD weenie summary
//          (LSD-Partial-*/weenie_summary.jsonl) that carries a creatureType.
//          The partial dump is the offline fallback when a monster was never
//          appraised (CreatureType is not in CreateObject — U4 row 17); a wcid
//          absent here simply has no species until an appraisal teaches it.
//   names  ACE ACE.Entity/Enum/CreatureType.cs, enum order from 0 = Invalid
//          (skipped), each identifier split at its CamelCase humps — the
//          retail display string (AppraisalSystem::InqCreatureDisplayName,
//          same strings as plugins/examine_format.js CREATURE_TYPE_NAMES:
//          "PhyntosWasp" → "Phyntos Wasp", "AunTumerok" → "Aun Tumerok").
//
// Both sources are read-only and outside the app; the committed JSON is what
// the browser and the gate tests read.
//
// Run (from apps/holtburger-web/):
//   node rynth/vt/tools/gen_creature_species.cjs           (check; exit 1 on drift, 0 when sources are absent)
//   node rynth/vt/tools/gen_creature_species.cjs --write   (regenerate)

"use strict";
const fs = require("fs");
const path = require("path");

const APP = path.resolve(__dirname, "..", "..", "..");
const OUT = path.join(APP, "rynth", "vt", "data", "creature_species.json");
const EXTERNAL = path.resolve(APP, "..", "..", "..");
const ACE_ENUM = path.join(EXTERNAL, "ACE", "Source", "ACE.Entity", "Enum", "CreatureType.cs");
const ITEM_TYPE_CREATURE = 16;

function findSummary() {
  try {
    for (const d of fs.readdirSync(EXTERNAL)) {
      if (!d.startsWith("LSD-Partial")) continue;
      const p = path.join(EXTERNAL, d, "weenie_summary.jsonl");
      if (fs.existsSync(p)) return p;
    }
  } catch (_) {
    /* no external dir */
  }
  return null;
}

/** "PhyntosWasp" → "Phyntos Wasp" (the retail display form). */
function displayName(ident) {
  return String(ident).replace(/([a-z])([A-Z])/g, "$1 $2");
}

/** CreatureType.cs text → { "<int>": "<display name>" } (Invalid = 0 skipped). */
function namesFromEnum(text) {
  const body = /enum\s+CreatureType\b[^{]*\{([\s\S]*?)\}/.exec(String(text));
  if (!body) throw new Error("CreatureType enum not found");
  const out = {};
  let next = 0;
  for (const raw of body[1].split(",")) {
    const line = raw.replace(/\/\/.*$/gm, "").trim();
    if (!line) continue;
    const m = /^([A-Za-z_][A-Za-z0-9_]*)\s*(?:=\s*(\d+))?$/.exec(line);
    if (!m) throw new Error(`unparsed enum member: ${line}`);
    const v = m[2] != null ? Number(m[2]) : next;
    next = v + 1;
    if (v === 0) continue;
    out[String(v)] = displayName(m[1]);
  }
  return out;
}

/** weenie_summary.jsonl text → { "<wcid>": creatureType } for creature rows.
 *  With `names`, rows whose creatureType has no enum name are dropped (the
 *  partial dump carries a few garbage values, e.g. wcid 30851 → 28640). */
function speciesFromSummary(text, names = null) {
  const out = {};
  for (let line of String(text).split(/\r?\n/)) {
    line = line.replace(/^﻿/, "").trim();
    if (!line) continue;
    let r;
    try {
      r = JSON.parse(line);
    } catch (_) {
      continue;
    }
    if (r.itemType !== ITEM_TYPE_CREATURE) continue;
    if (!Number.isInteger(r.creatureType) || r.creatureType <= 0) continue;
    if (!Number.isInteger(r.wcid) || r.wcid <= 0) continue;
    if (names && !names[String(r.creatureType)]) continue;
    out[String(r.wcid)] = r.creatureType;
  }
  return out;
}

function format(names, wcid) {
  const keys = Object.keys(wcid).sort((a, b) => Number(a) - Number(b));
  const rows = [];
  for (let i = 0; i < keys.length; i += 12) {
    rows.push("  " + keys.slice(i, i + 12).map((k) => `${JSON.stringify(k)}:${wcid[k]}`).join(","));
  }
  return (
    "{\n" +
    ' "v": 1,\n' +
    ` "_comment": ${JSON.stringify(
      "Generated by `node rynth/vt/tools/gen_creature_species.cjs --write`: wcid -> CreatureType from the LSD partial weenie summary (itemType 16 rows); names = ACE CreatureType.cs split at CamelCase (retail display names)."
    )},\n` +
    ` "names": ${JSON.stringify(names)},\n` +
    ' "wcid": {\n' +
    rows.join(",\n") +
    "\n }\n}\n"
  );
}

function main() {
  const write = process.argv.includes("--write");
  const summary = findSummary();
  const haveEnum = fs.existsSync(ACE_ENUM);
  if (!summary || !haveEnum) {
    if (write) {
      console.error(`--write needs ${!summary ? "LSD weenie_summary.jsonl under " + EXTERNAL : ACE_ENUM}`);
      process.exit(2);
    }
    console.log("0 corpus checks (LSD weenie summary or ACE CreatureType.cs absent)");
    return;
  }
  const names = namesFromEnum(fs.readFileSync(ACE_ENUM, "utf8"));
  const wcid = speciesFromSummary(fs.readFileSync(summary, "utf8"), names);
  if (write) {
    fs.mkdirSync(path.dirname(OUT), { recursive: true });
    fs.writeFileSync(OUT, format(names, wcid));
    console.log(`wrote ${Object.keys(wcid).length} wcids, ${Object.keys(names).length} names -> ${OUT}`);
    return;
  }
  const have = JSON.parse(fs.readFileSync(OUT, "utf8"));
  const fails = [];
  if (JSON.stringify(have.names) !== JSON.stringify(names)) fails.push("names differ from CreatureType.cs");
  const a = Object.keys(have.wcid || {});
  const b = Object.keys(wcid);
  if (a.length !== b.length) fails.push(`wcid count ${a.length} want ${b.length}`);
  for (const k of b) if (have.wcid[k] !== wcid[k]) fails.push(`wcid ${k}: ${have.wcid[k]} want ${wcid[k]}`);
  if (fails.length) {
    for (const f of fails.slice(0, 20)) console.log("FAIL " + f);
    process.exit(1);
  }
  console.log(`creature_species.json consistent (${b.length} wcids, ${Object.keys(names).length} names)`);
}

if (require.main === module) main();
module.exports = { displayName, namesFromEnum, speciesFromSummary };
